# The original visual remains byte-for-byte intact inside its bundled template.
# This extra bridge adds press-and-hold behavior to the existing Master setup
# button without changing its markup, styling, dimensions, or animations.
bridge = r'''
<script>
(function () {
  var holding = false;
  function masterButton(target) {
    if (!target || !target.closest) return null;
    var button = target.closest("button");
    if (!button) return null;
    var text = (button.textContent || "").toLowerCase();
    return (text.indexOf("register master") >= 0 || text.indexOf("holding") >= 0) ? button : null;
  }
  function call(name) {
    if (window.pywebview && window.pywebview.api) {
      window.pywebview.api.action(name, {}).catch(function (error) {
        console.error("Topup master action failed", error);
      });
    }
  }
  document.addEventListener("pointerdown", function (event) {
    var button = masterButton(event.target);
    if (!button || button.disabled) return;
    holding = true;
    if (button.setPointerCapture) button.setPointerCapture(event.pointerId);
    call("master_hold_start");
    event.preventDefault();
  });
  function stop(event) {
    if (!holding) return;
    holding = false;
    call("master_hold_stop");
    if (event) event.preventDefault();
  }
  document.addEventListener("pointerup", stop);
  document.addEventListener("pointercancel", stop);
  window.addEventListener("blur", stop);
})();
</script>
'''

