match = re.search(r'<script type="__bundler/template">\s*([\s\S]*?)\s*</script>', html)
if not match:
    raise RuntimeError("Perso bundled template was not found")
template = json.loads(match.group(1))
bridge_call = "    this.startBackendBridge();"
if template.count(bridge_call) != 1:
    raise RuntimeError("Perso backend bridge call was not found exactly once")
template = template.replace(bridge_call, "    /* Topup owns the single backend polling loop. */", 1)
marker = "\n</body></html>"
position = template.rfind(marker)
if position < 0:
    raise RuntimeError("Perso template body marker was not found")
template = template[:position] + bridge + home + template[position:]
encoded = json.dumps(template, ensure_ascii=False).replace("</script>", "<\\u002Fscript>")
replacement = '<script type="__bundler/template">\n' + encoded + '\n  </script>'
result = html[:match.start()] + replacement + html[match.end():]
DESTINATION.parent.mkdir(parents=True, exist_ok=True)
DESTINATION.write_text(result, encoding="utf-8")
print(f"Generated: {DESTINATION}")
